#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""Local corrections to the original independent English essays; preserve all blocks."""
import json
from pathlib import Path
from prepare_action_sources import Document
R=Path(__file__).resolve().parents[1];D=R/'data/frostpunk';M=D/'multilingual'
s=json.loads((M/'source-original.json').read_text())['articles']
changes={(1, 1): 'In Frostpunk, the center of the city is not a palace or a monument. It is a coal-fired generator. The first homes cluster around its heat. Later, steam hubs can extend heated areas and heaters can warm workplaces, but keeping people warm still consumes the resources on which the city depends.', (1, 7): 'These choices are not perfectly symmetrical, and the humane option is not useless. Child shelters sustain hope, and later apprenticeship laws let sheltered children assist medicine or research; cemeteries can sustain hope too. But the harsher option often produces the resource you need now, while transferring its cost into illness, discontent, hope, or death.', (1, 10): 'Child labor is not presented as an evil choice with an obviously easier alternative. Its first law puts additional hands into safe jobs, such as gathering posts, when a shortage of coal can threaten the generator. Dangerous work requires a further decision.', (1, 16): 'The game therefore gives you two views at once that are difficult to hold together: aggregate bars and particular names.', (1, 17): 'You can change staffing and shifts at individual buildings, and events sometimes let you help a particular person: a father seeking his missing child can receive supplies for the journey or be refused. Yet the city’s continuing needs keep drawing your attention back to aggregate coal, food, and labor. The particular life is visible without remaining the center of every decision.', (2, 1): 'Suppose you authorize child labor because the city needs more hands. The immediate shortage eases. The decision also leaves risks and events to manage, while hope and discontent still demand attention.', (2, 2): 'A second tool can now look attractive—not for the cold alone, but for the difficulties left behind by earlier decisions.', (2, 3): 'The Order branch, once it opens, offers many such instruments: neighborhood watch, guard stations, patrols, propaganda, prisons, foremen, informants, and eventually a New Order. They do not form one perfectly straight ladder. They branch and unlock one another. Yet moving deeper through the branch makes public response increasingly manageable.', (2, 10): 'Each new instrument promises relief. Watchtowers help sustain hope. Patrols lower discontent. Prisons can remove a group of people from the workforce and quiet the city. These tools have staffing, capacity, and conditions of use; they do not erase every risk. But another available button is another way to bring a crisis under control.', (2, 14): 'After a Propaganda Centre is established, an event reports young people writing “WAKE UP, PEOPLE!!!” on its outer wall. You can punish them or remove the writing.', (2, 15): 'The institution gives the protest an administrative destination. The words and their authors arrive together as an item awaiting treatment, with buttons beside them. Even opposition to the institution can become an object in the management process it serves.', (2, 16): 'The quieter option is to remove the writing without punishing its authors. Its displayed effect is a slight rise in hope. Punishment is not presented as the only choice that can improve the situation.', (2, 17): 'If you choose punishment, necessity is no longer the whole explanation. That button was available, but so was the one that did not punish.', (3, 10): 'The branches are not mechanically identical: their tools for production, care, and daily life differ. The comparison here concerns the use toward which their different forms of reassurance can be directed.', (3, 11): 'As a description of that political use, the convergence is chilling.', (3, 17): 'Before that moment, the captain is a public office. Citizens can complain, lose hope, raise discontent, and ultimately expel the person who occupies it. The final law replaces Hope with permanent Obedience or Devotion; it does not remove Discontent or every possibility of losing control.', (3, 18): 'You open the same book and make the same small signing gesture used for a child shelter. What follows is not quiet: the New Faith’s night of changes presents suppression, deaths, and people forced to renounce their former views.', (3, 19): 'The continuity lies in the act of signing, not in an absence of spectacle afterward. A constitutional transformation can begin through an interface already made familiar by dozens of practical decisions.', (4, 2): 'Then the game reviews the history you made. In an ending that judges you to have crossed the line, it asks whether survival was worth it. Other endings can affirm that the city thrived without crossing that line.', (4, 5): '## Reading the game’s boundary', (4, 6): 'The retrospective account of suffering and the verdict that a line has been crossed are not the same thing. The terminal Purpose laws, New Order and New Faith, bring that change into focus.', (4, 7): 'Child labor, extended shifts, food additives, and the treatment of the dead can all impose suffering. That suffering matters, but it does not make every decision identical to a law demanding permanent submission to the leader.', (4, 10): 'Read this way, the boundary concerns not only cruelty but the attempt to turn a population’s answer into a requirement to obey.', (4, 11): '## The relief offered by control', (4, 12): 'Strategy guides often advise that once a player has crossed the line, continuing to the end of the branch can make management easier. Hope no longer needs to be maintained in the same way, while other tools suppress discontent. That relief does not guarantee lasting stability or prove that every coercive measure was necessary.', (4, 13): 'That is why the question cannot be reduced to a body count. The usefulness of a tool does not by itself settle whether the population should be required to submit to the person who uses it.', (4, 20): 'The Fall of Winterhome begins with a city in collapse. Its generator ultimately cannot be saved, but evacuation remains a goal that can be achieved in part. You prepare a land dreadnought and send people and supplies to it before complete failure. Space and time limit whom you can take.', (4, 21): 'The Book of Laws has not become powerless here: New Order can still be enacted. It can extend the tools of management, but it cannot turn the doomed generator into a permanently viable city. The question of who receives the remaining places persists.', (4, 22): 'The loss of the city does not remove the ruler’s capacity to overreach. Winterhome leaves those tools in your hands while making you confront the people you take away and those left behind.', (4, 23): 'Another signature cannot decide the allocation problem for you. Whether a city can be saved and how its people may be treated are not the same question.', (1, 2): 'You lead the people who arrive at this crater. In everyday management, however, the captain is not a controllable citizen whose body must be housed and kept warm. The citizens endure hunger, cold, illness, and lost limbs. You endure the possibility that the city will collapse and that they will remove you from office.', (2, 18): 'Return now to the fork where these paths first opened. It began not with another law, but with news from a dead city.', (3, 1): 'Your scouts find Winterhome, and news reaches your city. Another settlement, established before yours, has already failed.'}
arts=[];records=[]
for i,a in enumerate(s,1):
 body=[changes.get((i,j),b) for j,b in enumerate(a['body_en'],1)]
 d=Document((R/a['source_html']).read_text());title=next(n.text().strip() for n in d.root.walk() if n.has('essay-page-title','lang-en'));deck=body[0]
 arts.append(dict(slug=a['slug'],title=title,deck=deck,body=body,edition_note='An independently structured English essay, retained with local factual and dependent-interpretation corrections. Full-game spoilers.'))
 records.append(dict(slug=a['slug'],original_body=a['body_en'],revised_body=body,block_mapping=[dict(target_block=j,original_block=j,kind='local-correction' if (i,j) in changes else 'retained') for j in range(1,len(body)+1)]))
(M/'en.json').write_text(json.dumps(dict(language='en',series=dict(title='Reading Frostpunk',deck='Law, cumulative expediency, and the place left for an answer.',intro=[]),ui=dict(series='Reading Frostpunk'),articles=arts),ensure_ascii=False,indent=2)+'\n')
(D/'english-corrections.json').write_text(json.dumps(dict(policy='Retain all 83 original independent English blocks; local factual and direct dependent corrections only.',articles=records),ensure_ascii=False,indent=2)+'\n')
print(len(changes),'local corrections; counts',[len(a['body']) for a in arts])
